// ===== Banco de preguntas · RIPA (luces, marcas y reglas) · estilo DGMM =====
// fig: {k:"n"|"d", v: texto de la vista, l:[[color,x,y],...]} (noche) | {k:"d", v, s:[formas]} (día)
const TOPICS = {
  def: "Sectores y definiciones",
  alc: "Alcances de las luces",
  pm:  "Propulsión mecánica",
  rem: "Remolque y empuje",
  vel: "Vela y remos",
  pes: "Pesca",
  sg:  "Sin gobierno y maniobra restringida",
  cp:  "Restringido por calado y práctico",
  fon: "Fondeados y varados",
  mar: "Marcas diurnas",
  gen: "Reglas de rumbo y señales acústicas"
};
const LIGHT_TOPICS = ["def","alc","pm","rem","vel","pes","sg","cp","fon","mar"];

const Q = [
// ---------- Sectores y definiciones ----------
{id:"d1",t:"def",q:"La «luz de tope» es:",o:["Una luz blanca colocada sobre el eje longitudinal del buque, que muestra su luz sin interrupción en un arco de horizonte de 225°","Una luz blanca todo horizonte colocada en el punto más alto del buque","Una luz blanca de 135° colocada lo más cerca posible de la popa","Una luz amarilla de 225° que exhiben los buques que remolcan"],a:0,e:"Blanca, sobre el eje proa-popa, 225°: desde la proa hasta 22,5° a popa del través por cada banda.",r:"Regla 21 a)"},
{id:"d2",t:"def",q:"Cada una de las luces de costado muestra su luz sin interrupción en un arco de horizonte de:",o:["225°","135°","112,5°","180°"],a:2,e:"Verde a estribor y roja a babor, 112,5° cada una: desde la proa hasta 22,5° a popa del través de su banda. Las dos juntas suman 225°, lo mismo que la luz de tope.",r:"Regla 21 b)"},
{id:"d3",t:"def",q:"La luz de alcance:",o:["Es de color amarillo","Debe colocarse lo más cerca posible de la proa","Es blanca, se coloca lo más cerca posible de la popa y es visible en un arco de 135°","Ninguna de las respuestas anteriores es correcta"],a:2,e:"Blanca, lo más cerca posible de la popa, 135° (67,5° a cada banda contados desde la popa). 225° de tope + 135° de alcance = 360°: el horizonte completo.",r:"Regla 21 c)"},
{id:"d4",t:"def",q:"La «luz de remolque» es:",o:["Una luz blanca de las mismas características que la luz de alcance","Una luz amarilla de las mismas características que la luz de alcance","Una luz amarilla todo horizonte","Una luz amarilla centelleante"],a:1,e:"Amarilla, 135° hacia popa, igual que la de alcance. Va en línea vertical por encima de la luz de alcance.",r:"Regla 21 d)"},
{id:"d5",t:"def",q:"Según el RIPA, una «luz centelleante» es la que produce destellos a intervalos regulares con una frecuencia de:",o:["120 o más destellos por minuto","60 destellos por minuto","Entre 50 y 80 destellos por minuto","30 destellos por minuto"],a:0,e:"120 destellos por minuto o más. La usan, por ejemplo, los aerodeslizadores (amarilla) y las naves de vuelo rasante (roja).",r:"Regla 21 f)"},
{id:"d6",t:"def",q:"La luz de tope es visible:",o:["Desde la proa hasta el través de cada banda","Desde la proa hasta 22,5° a popa del través de cada banda","En todo el horizonte","Desde la popa hasta 67,5° de cada banda"],a:1,e:"Hasta 22,5° a popa del través. A partir de ahí empieza el sector de la luz de alcance.",r:"Regla 21 a)"},
{id:"d7",t:"def",q:"Las luces prescritas en el reglamento deben exhibirse:",o:["Solo entre la puesta y la salida del sol","Desde la puesta hasta la salida del sol y, además, de día con visibilidad reducida","Solo con visibilidad reducida","Únicamente cuando haya otros buques a la vista"],a:1,e:"De noche siempre, y de día también cuando haya visibilidad reducida (y en cualquier otra circunstancia en que se considere necesario). Las marcas se exhiben de día.",r:"Regla 20 b) y c)"},
{id:"d8",t:"def",q:"De noche, un buque que se aproxima a otro desde una marcación mayor de 22,5° a popa del través de este último:",o:["Solo podrá ver la luz de alcance del otro buque, y ninguna de sus luces de costado","Verá su luz de tope y una de las de costado","Verá ambas luces de costado","Verá solo su luz de tope"],a:0,e:"Esa zona es exactamente el sector de la luz de alcance. Por eso la situación de «alcance» se define con ese ángulo: si de noche solo ves su luz de alcance, eres tú quien alcanza y debes apartarte.",r:"Reglas 13 b) y 21 c)"},
{id:"d9",t:"def",q:"En un buque de eslora inferior a 20 metros, las luces de costado:",o:["Pueden ir combinadas en un solo farol, colocado en el eje longitudinal del buque","Deben ser obligatoriamente dos faroles independientes","Pueden sustituirse por una luz blanca todo horizonte","No son obligatorias"],a:0,e:"Por debajo de 20 m se permite el farol combinado verde-rojo en el eje proa-popa.",r:"Regla 21 b)"},

// ---------- Alcances ----------
{id:"a1",t:"alc",q:"En un buque de 50 metros de eslora o más, la luz de tope debe ser visible a una distancia mínima de:",o:["3 millas","5 millas","6 millas","2 millas"],a:2,e:"≥ 50 m: tope 6 millas; costado, alcance, remolque y todo horizonte 3 millas.",r:"Regla 22 a)"},
{id:"a2",t:"alc",q:"En un buque de 15 metros de eslora, la luz de tope debe tener un alcance mínimo de:",o:["2 millas","3 millas","5 millas","6 millas"],a:1,e:"Entre 12 y 50 m la tope es de 5 millas, salvo si el buque mide menos de 20 m: entonces bastan 3 millas. Costado, alcance y todo horizonte: 2 millas.",r:"Regla 22 b)"},
{id:"a3",t:"alc",q:"En una embarcación de 9 metros de eslora, las luces de costado deben ser visibles al menos a:",o:["1 milla","2 millas","3 millas","0,5 millas"],a:0,e:"< 12 m: tope 2, costado 1, alcance 2, remolque 2, todo horizonte 2. Las de costado son las únicas de 1 milla.",r:"Regla 22 c)"},
{id:"a4",t:"alc",q:"En un buque de 30 metros de eslora, la luz de tope debe ser visible a una distancia mínima de:",o:["3 millas","5 millas","6 millas","2 millas"],a:1,e:"De 20 a 50 m: tope 5 millas. Las demás, 2 millas.",r:"Regla 22 b)"},
{id:"a5",t:"alc",q:"En un buque de 30 metros, las luces de costado, de alcance y todo horizonte deben ser visibles al menos a:",o:["1 milla","2 millas","3 millas","5 millas"],a:1,e:"De 12 a 50 m: costado, alcance, remolque y todo horizonte, 2 millas.",r:"Regla 22 b)"},
{id:"a6",t:"alc",q:"En una embarcación de 10 metros, la luz blanca todo horizonte debe tener un alcance mínimo de:",o:["1 milla","2 millas","3 millas","No se exige alcance mínimo"],a:1,e:"< 12 m: todo horizonte 2 millas (solo las de costado bajan a 1 milla).",r:"Regla 22 c)"},
{id:"a7",t:"alc",q:"En un buque de 60 metros de eslora, las luces de costado deben ser visibles al menos a:",o:["2 millas","3 millas","5 millas","6 millas"],a:1,e:"≥ 50 m: todas 3 millas, salvo la tope, que es de 6.",r:"Regla 22 a)"},

// ---------- Propulsión mecánica ----------
{id:"p1",t:"pm",q:"Un buque de propulsión mecánica de 60 metros de eslora, en navegación, exhibirá:",o:["Una luz de tope a proa, luces de costado y luz de alcance","Una luz de tope a proa, una segunda luz de tope más alta a popa, luces de costado y luz de alcance","Dos luces de tope en línea vertical, luces de costado y luz de alcance","Una luz blanca todo horizonte y luces de costado"],a:1,e:"La segunda luz de tope (a popa y más alta que la de proa) es obligatoria desde 50 m. Dos topes en línea vertical es otra cosa: remolque o empuje.",r:"Regla 23 a)"},
{id:"p2",t:"pm",q:"Un buque de propulsión mecánica de 30 metros de eslora, ¿está obligado a exhibir una segunda luz de tope?",o:["Sí, siempre","No; solo es obligatoria en buques de 50 metros o más, aunque puede llevarla","Solo cuando navega por un dispositivo de separación del tráfico","Solo si es un buque de pasaje"],a:1,e:"Por debajo de 50 m la segunda tope es opcional.",r:"Regla 23 a) ii)"},
{id:"p3",t:"pm",q:"Una embarcación de propulsión mecánica de eslora inferior a 12 metros podrá exhibir, en lugar de las luces de tope y alcance:",o:["Una luz blanca todo horizonte, además de las luces de costado","Solo una luz de alcance","Una luz roja sobre una verde en el tope","Únicamente una linterna eléctrica"],a:0,e:"Blanca todo horizonte + costados. Es la configuración típica de una lancha de recreo.",r:"Regla 23 d) i)"},
{id:"p4",t:"pm",q:"Una embarcación de propulsión mecánica de eslora inferior a 7 metros cuya velocidad máxima no exceda de 7 nudos podrá exhibir:",o:["Una luz blanca todo horizonte y, si es posible, también luces de costado","Solo luces de costado","Una luz amarilla centelleante","No está obligada a exhibir ninguna luz"],a:0,e:"< 7 m y ≤ 7 nudos: basta una blanca todo horizonte (y costados si es posible).",r:"Regla 23 d) ii)"},
{id:"p5",t:"pm",q:"Un aerodeslizador que navega sin desplazamiento exhibirá, además de las luces de un buque de propulsión mecánica:",o:["Una luz roja centelleante todo horizonte","Una luz amarilla centelleante todo horizonte","Dos luces rojas todo horizonte en línea vertical","Una luz azul centelleante"],a:1,e:"Amarilla centelleante todo horizonte. La roja centelleante de alta intensidad es la de las naves de vuelo rasante (WIG).",r:"Regla 23 b)"},
{id:"p6",t:"pm",q:"Navegando a motor de noche, vemos por la proa las luces de la figura, con demora constante. Se trata de:",o:["Un buque de propulsión mecánica que viene de vuelta encontrada: ambos debemos caer a estribor","Un buque remolcando visto por la proa: debemos mantener rumbo y velocidad","Un velero visto por la proa","Un buque fondeado"],a:0,fig:{k:"n",v:"Por nuestra proa",l:[["w",113,74],["w",127,40],["g",100,98],["r",140,98]]},e:"Dos topes escalonadas (la de proa más baja) y las dos luces de costado a la vez: lo vemos de frente. De frente, su verde queda a TU izquierda y su roja a TU derecha. Vuelta encontrada: ambos caen a estribor.",r:"Reglas 14 y 23"},
{id:"p7",t:"pm",q:"Navegando a motor, observamos por nuestra amura de babor las luces de la figura, con demora constante. ¿Qué debemos hacer?",o:["Caer a estribor para pasar por su popa","Mantener rumbo y velocidad, vigilando: el otro buque nos tiene por su estribor y debe apartarse","Caer a babor","Parar las máquinas inmediatamente"],a:1,fig:{k:"n",v:"Por nuestra amura de babor",l:[["w",168,72],["w",92,46],["g",146,98]]},e:"Vemos su verde: estamos en su costado de estribor. Él nos tiene por su estribor, así que es él quien se aparta (cruce). Nosotros seguimos a rumbo, preparados para actuar si no maniobra.",r:"Reglas 15 y 17"},
{id:"p8",t:"pm",q:"Navegando a motor, observamos por nuestra amura de estribor las luces de la figura, con demora constante. Debemos:",o:["Mantener rumbo y velocidad","Apartarnos de su derrota, preferiblemente cayendo a estribor para pasar por su popa","Caer a babor para cruzar por su proa","Emitir cinco pitadas cortas y mantener el rumbo"],a:1,fig:{k:"n",v:"Por nuestra amura de estribor",l:[["w",72,72],["w",148,46],["r",94,98]]},e:"Vemos su roja: estamos en su costado de babor, y lo tenemos por nuestro estribor. En un cruce se aparta quien tiene al otro por estribor: nosotros. Evitamos cruzar por su proa.",r:"Regla 15"},
{id:"p9",t:"pm",q:"De noche vemos únicamente una luz blanca. Puede tratarse de:",o:["La luz de alcance de un buque al que nos aproximamos por su popa","Un buque fondeado de eslora inferior a 50 metros","Una embarcación de vela de eslora inferior a 7 metros que muestra una linterna blanca","Todas las respuestas anteriores son correctas"],a:3,fig:{k:"n",v:"Por nuestra proa",l:[["w",120,82]]},e:"Una sola blanca es ambigua: luz de alcance, fondeado de menos de 50 m, embarcación pequeña con blanca todo horizonte o linterna. Ante la duda, vigilar la demora y actuar con prudencia.",r:"Reglas 21, 23, 25 y 30"},
{id:"p10",t:"pm",q:"Una nave de vuelo rasante (WIG), cuando despega, aterriza o vuela cerca de la superficie, exhibirá además:",o:["Una luz roja centelleante todo horizonte de alta intensidad","Una luz amarilla centelleante todo horizonte","Dos luces rojas en línea vertical","Una luz verde centelleante"],a:0,e:"Roja centelleante de alta intensidad. La amarilla centelleante es del aerodeslizador.",r:"Regla 23 c)"},

// ---------- Remolque y empuje ----------
{id:"r1",t:"rem",q:"Un buque de propulsión mecánica que remolca, cuando la longitud del remolque (desde la popa del remolcador hasta el extremo de popa del remolcado) excede de 200 metros, exhibirá a proa:",o:["Dos luces de tope en línea vertical","Tres luces de tope en línea vertical","Una luz de tope y una luz amarilla","Tres luces rojas en línea vertical"],a:1,e:"Más de 200 m: tres topes en vertical. 200 m o menos: dos.",r:"Regla 24 a) i)"},
{id:"r2",t:"rem",q:"Un remolcador con una longitud de remolque de 150 metros exhibirá a proa:",o:["Una luz de tope","Dos luces de tope en línea vertical","Tres luces de tope en línea vertical","Dos luces de tope en línea horizontal"],a:1,e:"Hasta 200 m de remolque: dos topes en vertical.",r:"Regla 24 a) i)"},
{id:"r3",t:"rem",q:"Además de las luces de costado y de alcance, el buque que remolca por la popa exhibirá:",o:["Una luz de remolque amarilla en línea vertical por encima de la luz de alcance","Una luz amarilla en el tope del palo","Una luz roja por debajo de la de alcance","Una luz blanca todo horizonte a popa"],a:0,e:"Amarilla sobre blanca a popa: quien te alcance sabe que delante hay un remolque.",r:"Regla 24 a) iv)"},
{id:"r4",t:"rem",q:"De día, cuando la longitud del remolque excede de 200 metros:",o:["Solo el remolcador exhibe una marca bicónica","Remolcador y remolcado exhibirán una marca bicónica en el lugar más visible","Ambos exhiben una bola","Ambos exhiben un cilindro"],a:1,e:"Marca bicónica (dos conos unidos por la base) en los dos buques.",r:"Regla 24 a) v) y e) iii)"},
{id:"r5",t:"rem",q:"De noche, por nuestra proa y navegando a su mismo rumbo, vemos las luces de la figura. Se trata de:",o:["Un buque sin gobierno visto por la popa","Un buque remolcando, visto por su popa","Un buque de práctico","Un buque fondeado"],a:1,fig:{k:"n",v:"Por nuestra proa, mismo rumbo",l:[["y",120,58],["w",120,80]]},e:"Amarilla sobre blanca, ambas de 135° hacia popa: luz de remolque sobre luz de alcance. Detrás del remolcador viene el remolcado: no cruces entre ambos.",r:"Regla 24 a) iv)"},
{id:"r6",t:"rem",q:"¿Qué indican las luces de la figura, vistas por la proa?",o:["Un buque de propulsión mecánica de más de 50 metros","Un buque remolcando, con una longitud de remolque superior a 200 metros","Un buque remolcando, con una longitud de remolque inferior a 200 metros","Un buque con capacidad de maniobra restringida"],a:1,fig:{k:"n",v:"Por nuestra proa",l:[["w",120,36],["w",120,54],["w",120,72],["g",102,98],["r",138,98]]},e:"Tres blancas exactamente en vertical + costados: remolque de más de 200 m. Con dos en vertical sería un remolque de 200 m o menos (o un buque empujando).",r:"Regla 24 a) i)"},
{id:"r7",t:"rem",q:"Un buque que está siendo remolcado exhibirá:",o:["Luces de costado y luz de alcance; y marca bicónica si el remolque excede de 200 metros","Dos luces de tope en línea vertical","Una luz de remolque amarilla","Solo una luz blanca todo horizonte"],a:0,e:"El remolcado no lleva tope: costados y alcance (y bicónica de día si > 200 m).",r:"Regla 24 e)"},
{id:"r8",t:"rem",q:"Un buque de propulsión mecánica que empuja hacia proa (sin formar una unidad compuesta) exhibirá:",o:["Dos luces de tope en línea vertical, luces de costado y luz de alcance","Dos luces de tope, luces de costado, luz de alcance y luz de remolque amarilla","Tres luces de tope y luz de remolque","Las mismas luces que un buque sin gobierno"],a:0,e:"La luz amarilla de remolque solo la lleva quien remolca por la popa. Quien empuja: dos topes en vertical, costados y alcance.",r:"Regla 24 c)"},
{id:"r9",t:"rem",q:"Un remolcador cuyo remolque le impide gravemente apartarse de su derrota exhibirá, además de las luces de remolque:",o:["Dos luces rojas todo horizonte en línea vertical","Roja, blanca y roja en línea vertical, como un buque con capacidad de maniobra restringida","Tres luces rojas en línea vertical","Una luz verde todo horizonte"],a:1,e:"Pasa a ser un buque con capacidad de maniobra restringida: añade roja-blanca-roja.",r:"Reglas 24 a) y 27 b)"},
{id:"r10",t:"rem",q:"Cuando el buque que empuja y el empujado están rígidamente unidos formando una unidad compuesta:",o:["Se consideran un buque de propulsión mecánica y exhiben sus luces","Exhiben las luces de remolque","Exhiben las luces de buque sin gobierno","Deben exhibir siempre la marca bicónica"],a:0,e:"La unidad compuesta se trata como un único buque de propulsión mecánica.",r:"Regla 24 b)"},

// ---------- Vela y remos ----------
{id:"v1",t:"vel",q:"Un buque de vela en navegación exhibirá:",o:["Luz de tope, luces de costado y luz de alcance","Luces de costado y luz de alcance","Solo una luz blanca todo horizonte","Obligatoriamente una luz roja sobre una verde en el tope"],a:1,e:"Un velero no lleva luz de tope: esa es la diferencia clave con un buque a motor.",r:"Regla 25 a)"},
{id:"v2",t:"vel",q:"En un buque de vela de eslora inferior a 20 metros, las luces de costado y de alcance:",o:["Pueden ir combinadas en un solo farol en el tope del palo o cerca de él","Deben ir siempre en faroles separados","Pueden sustituirse por dos luces verdes en línea vertical","Deben ir en la cubierta"],a:0,e:"Es el farol tricolor del tope del palo.",r:"Regla 25 b)"},
{id:"v3",t:"vel",q:"Además de las luces prescritas, un buque de vela en navegación podrá exhibir en el tope del palo dos luces todo horizonte en línea vertical:",o:["Dos rojas","Dos verdes","Roja la superior y verde la inferior","Verde la superior y roja la inferior"],a:2,e:"«Rojo sobre verde, el velero se ve». Son opcionales y no pueden exhibirse junto con el farol tricolor.",r:"Regla 25 c)"},
{id:"v4",t:"vel",q:"Un buque de vela que navega propulsado también por motor exhibirá de día:",o:["Una bola a proa","Un cono con el vértice hacia abajo, a proa","Un cono con el vértice hacia arriba","Un cilindro"],a:1,e:"Cono con el vértice hacia abajo. De noche lleva las luces de buque de propulsión mecánica: a efectos del reglamento es un buque a motor.",r:"Regla 25 e)"},
{id:"v5",t:"vel",q:"Un buque de vela de eslora inferior a 7 metros que no pueda exhibir las luces de costado y alcance:",o:["Tendrá a mano una linterna eléctrica o farol de luz blanca para mostrarla con tiempo suficiente para evitar el abordaje","No necesita exhibir ninguna luz","Debe fondear al anochecer","Exhibirá dos luces rojas"],a:0,e:"Linterna o farol blanco listo para mostrar a tiempo.",r:"Regla 25 d) i)"},
{id:"v6",t:"vel",q:"Las luces todo horizonte roja sobre verde de los veleros:",o:["Pueden exhibirse junto con el farol combinado del tope","No pueden exhibirse junto con el farol combinado del tope","Son obligatorias en buques de más de 20 metros","Solo se exhiben estando fondeado"],a:1,e:"O tricolor, o roja-verde todo horizonte con sus costados y alcance normales. Nunca ambos.",r:"Regla 25 c)"},
{id:"v7",t:"vel",q:"¿Qué buque exhibe las luces de la figura?",o:["Un buque de vela en navegación, visto por su costado de estribor","Un buque dedicado a la pesca de arrastre","Un buque de práctico","Un buque sin gobierno con arrancada"],a:0,fig:{k:"n",v:"De través",l:[["r",120,30],["g",120,48],["g",150,98]]},e:"Roja sobre verde todo horizonte en el tope = velero (luces opcionales). Abajo, la verde de costado: lo vemos por estribor. No confundir con verde sobre blanca (arrastre) ni con blanca sobre roja (práctico).",r:"Regla 25 c)"},
{id:"v8",t:"vel",q:"Navegando a motor de noche, observamos por la amura de babor una única luz verde que se aproxima con demora constante. Debemos:",o:["Mantener rumbo y velocidad, porque el otro buque está por nuestro babor","Apartarnos de su derrota: probablemente es un buque de vela","Caer a babor","Ambos buques deben caer a estribor"],a:1,fig:{k:"n",v:"Por nuestra amura de babor",l:[["g",120,94]]},e:"Una verde sola, sin luz de tope: un buque sin tope visto por estribor, es decir, un velero (o una embarcación de remos). Un buque de propulsión mecánica debe apartarse de un velero, aunque esté por su babor.",r:"Regla 18 a)"},
{id:"v9",t:"vel",q:"Una embarcación de remos podrá exhibir:",o:["Las luces prescritas para los buques de vela o, si no, tener a mano una linterna o farol de luz blanca","Una luz amarilla centelleante","Dos luces blancas en línea vertical","Solo luces de costado"],a:0,e:"Luces de velero o linterna blanca lista para mostrar.",r:"Regla 25 d) ii)"},

// ---------- Pesca ----------
{id:"f1",t:"pes",q:"Un buque dedicado a la pesca de arrastre exhibirá dos luces todo horizonte en línea vertical:",o:["Roja la superior y blanca la inferior","Verde la superior y blanca la inferior","Blanca la superior y roja la inferior","Roja la superior y verde la inferior"],a:1,e:"«Verde sobre blanco, voy arrastrando». Roja sobre blanca es pesca no de arrastre; blanca sobre roja, práctico.",r:"Regla 26 b) i)"},
{id:"f2",t:"pes",q:"Un buque dedicado a la pesca que no sea de arrastre exhibirá:",o:["Roja sobre blanca, todo horizonte, en línea vertical","Verde sobre blanca","Blanca sobre roja","Dos luces rojas en línea vertical"],a:0,e:"«Rojo sobre blanco, estoy pescando» (palangre, cerco, redes fijas...).",r:"Regla 26 c) i)"},
{id:"f3",t:"pes",q:"La marca diurna de un buque dedicado a la pesca es:",o:["Dos conos unidos por sus vértices en línea vertical","Una marca bicónica","Dos bolas en línea vertical","Un cono con el vértice hacia abajo"],a:0,e:"Dos conos unidos por los vértices (forma de reloj de arena). La bicónica (unidos por las bases) es del remolque de más de 200 m.",r:"Regla 26 b) i) y c) i)"},
{id:"f4",t:"pes",q:"Un pesquero que no es de arrastre, con el aparejo extendido más de 150 metros horizontalmente, exhibirá en la dirección del aparejo:",o:["Una luz blanca todo horizonte o, de día, un cono con el vértice hacia arriba","Una luz roja todo horizonte o un cono con el vértice hacia abajo","Una luz verde o una bola","Dos luces amarillas"],a:0,e:"Blanca todo horizonte / cono vértice arriba, señalando hacia donde está el aparejo.",r:"Regla 26 c) ii)"},
{id:"f5",t:"pes",q:"La luz de tope situada a popa y más alta que la luz verde de un arrastrero:",o:["Es obligatoria en buques de 50 metros o más; los de menor eslora pueden exhibirla","Es obligatoria en todos los arrastreros","Está prohibida","Se exhibe solo cuando el buque está sin arrancada"],a:0,e:"Igual que la segunda tope de los buques a motor: obligatoria desde 50 m.",r:"Regla 26 b) ii)"},
{id:"f6",t:"pes",q:"Las luces de la figura, sin ninguna otra visible, corresponden a:",o:["Un buque de práctico en servicio","Un buque dedicado a la pesca de arrastre, sin arrancada","Un buque dedicado a la pesca no de arrastre, con arrancada","Un velero con sus luces opcionales"],a:1,fig:{k:"n",v:"Por nuestra proa",l:[["g",120,48],["w",120,70]]},e:"Verde sobre blanca = arrastre. No se ven costados ni alcance: no tiene arrancada (esas luces solo se exhiben con arrancada).",r:"Regla 26 b)"},
{id:"f7",t:"pes",q:"Las luces de la figura corresponden a:",o:["Un buque dedicado a la pesca no de arrastre, con arrancada, visto por su babor","Un buque de práctico visto por babor","Un buque sin gobierno","Un pesquero de arrastre visto por estribor"],a:0,fig:{k:"n",v:"De través",l:[["r",120,46],["w",120,66],["r",92,98]]},e:"Roja sobre blanca = pesca no de arrastre. La roja de abajo es su luz de costado de babor: tiene arrancada y lo vemos por babor.",r:"Regla 26 c)"},
{id:"f8",t:"pes",q:"Un buque dedicado a la pesca, sin arrancada:",o:["No exhibirá luces de costado ni de alcance, pero sí las de pesca","Mantendrá encendidas las luces de costado","Exhibirá además las luces de fondeo","Exhibirá dos luces rojas"],a:0,e:"Costados y alcance solo con arrancada.",r:"Regla 26 b) iii) y c) iii)"},

// ---------- Sin gobierno y maniobra restringida ----------
{id:"g1",t:"sg",q:"Un buque sin gobierno exhibirá:",o:["Dos luces rojas todo horizonte en línea vertical y, de día, dos bolas","Tres luces rojas en línea vertical y un cilindro","Roja, blanca y roja en línea vertical","Dos luces rojas y una bola"],a:0,e:"Dos rojas / dos bolas. Tres rojas / cilindro es restringido por su calado.",r:"Regla 27 a)"},
{id:"g2",t:"sg",q:"Un buque sin gobierno, cuando tiene arrancada, exhibirá además:",o:["Luces de costado y luz de alcance","Luces de tope","Luz de remolque","Ninguna luz adicional"],a:0,e:"Costados y alcance, pero nunca luz de tope.",r:"Regla 27 a) iii)"},
{id:"g3",t:"sg",q:"Un buque con capacidad de maniobra restringida exhibirá tres luces todo horizonte en línea vertical:",o:["Roja, blanca y roja","Blanca, roja y blanca","Tres rojas","Roja, verde y roja"],a:0,e:"Roja-blanca-roja. Con arrancada, añade topes, costados y alcance; fondeado, las de fondeo.",r:"Regla 27 b) i)"},
{id:"g4",t:"sg",q:"¿Cuál de las siguientes marcas identifica a un buque con capacidad de maniobra restringida?",o:["Una marca bicónica","Dos conos unidos por sus vértices en línea vertical","Dos bolas en línea vertical","Tres marcas en línea vertical: la más alta y la más baja bolas, y la central bicónica"],a:3,e:"Bola-bicónica-bola, igual que sus luces roja-blanca-roja: las rojas son bolas y la blanca es la bicónica.",r:"Regla 27 b) ii)"},
{id:"g5",t:"sg",q:"¿Cuál de los siguientes NO se considera «buque con capacidad de maniobra restringida»?",o:["Un buque dedicado a operaciones de dragado","Un buque dedicado a la pesca de arrastre","Un buque dedicado a operaciones de dragado de minas","Un buque que efectúa aprovisionamiento en navegación"],a:1,e:"El arrastrero tiene su propia categoría: buque dedicado a la pesca. Son de maniobra restringida: balizamiento y cables, dragados y operaciones submarinas, aprovisionamiento en navegación, aeronaves, dragado de minas y remolques que impiden apartarse.",r:"Regla 3 g)"},
{id:"g6",t:"sg",q:"Un buque dedicado a dragados con una obstrucción en una de sus bandas exhibirá, además de roja-blanca-roja:",o:["Dos rojas en línea vertical en la banda de la obstrucción y dos verdes en línea vertical en la banda por la que puede pasar otro buque","Dos verdes en la banda de la obstrucción y dos rojas en la banda libre","Una luz amarilla en la banda de la obstrucción","Tres luces verdes en triángulo"],a:0,e:"Rojo = no pasar; verde = paso libre. De día: dos bolas en la banda obstruida y dos bicónicas en la banda libre.",r:"Regla 27 d)"},
{id:"g7",t:"sg",q:"Una embarcación pequeña dedicada a operaciones de buceo que no pueda exhibir las marcas de buque con maniobra restringida exhibirá:",o:["Una réplica rígida de la bandera «A» del Código Internacional de Señales, de al menos 1 metro de altura","Una bandera roja con una franja blanca diagonal","Dos bolas en línea vertical","Una bandera amarilla"],a:0,e:"El RIPA pide la réplica rígida de la bandera «A» (blanca y azul), de 1 m como mínimo.",r:"Regla 27 e)"},
{id:"g8",t:"sg",q:"Un buque dedicado a operaciones de dragado de minas exhibirá:",o:["Tres luces verdes todo horizonte (una en el tope del palo de proa y una en cada extremo de la verga) o tres bolas","Tres luces rojas en línea vertical","Dos luces verdes en línea vertical","Roja, blanca y roja"],a:0,e:"Indica que es peligroso aproximarse a menos de 1.000 metros.",r:"Regla 27 f)"},
{id:"g9",t:"sg",q:"Navegando de noche vemos por la proa, a nuestro mismo rumbo, las luces de la figura. Se trata de:",o:["Un buque sin gobierno, con arrancada, visto por su popa","Un buque restringido por su calado","Un buque fondeado","Un buque remolcando"],a:0,fig:{k:"n",v:"Por nuestra proa, mismo rumbo",l:[["r",120,40],["r",120,60],["w",120,96]]},e:"Dos rojas en vertical = sin gobierno. La blanca baja es su luz de alcance: tiene arrancada y lo vemos por la popa.",r:"Regla 27 a)"},
{id:"g10",t:"sg",q:"Las luces de la figura, sin ninguna otra visible, indican:",o:["Buque sin gobierno","Buque con capacidad de maniobra restringida, sin arrancada","Buque restringido por su calado","Buque de práctico fondeado"],a:1,fig:{k:"n",v:"Por nuestra proa",l:[["r",120,34],["w",120,56],["r",120,78]]},e:"Roja-blanca-roja = maniobra restringida. Sin costados ni alcance: sin arrancada.",r:"Regla 27 b)"},
{id:"g11",t:"sg",q:"La figura muestra tres luces verdes todo horizonte. Corresponden a:",o:["Un buque dedicado al dragado de minas: es peligroso aproximarse a menos de 1.000 metros","Un pesquero de arrastre","Un velero con sus luces opcionales","Un buque restringido por su calado"],a:0,fig:{k:"n",v:"Por nuestra proa",l:[["g",120,30],["g",86,56],["g",154,56]]},e:"Tres verdes en triángulo (tope y extremos de la verga) = dragaminas.",r:"Regla 27 f)"},
{id:"g12",t:"sg",q:"Los buques de eslora inferior a 12 metros, salvo los dedicados a operaciones de buceo:",o:["No están obligados a exhibir las luces y marcas de buque sin gobierno o con maniobra restringida","Deben exhibir siempre esas luces","Exhiben solo las marcas, no las luces","Exhiben una luz amarilla"],a:0,e:"Exención para < 12 m, excepto buceo.",r:"Regla 27 g)"},

// ---------- Calado y práctico ----------
{id:"c1",t:"cp",q:"Un buque restringido por su calado podrá exhibir, además de las luces de buque de propulsión mecánica:",o:["Tres luces rojas todo horizonte en línea vertical o, de día, un cilindro","Dos luces rojas en línea vertical o dos bolas","Roja, blanca y roja, o bola-bicónica-bola","Una luz azul o un cono"],a:0,e:"Tres rojas / cilindro. Y conserva sus luces normales de buque a motor (topes, costados, alcance).",r:"Regla 28"},
{id:"c2",t:"cp",q:"Un buque en servicio de practicaje exhibirá en el tope o cerca de él dos luces todo horizonte en línea vertical:",o:["Blanca la superior y roja la inferior","Roja la superior y blanca la inferior","Verde la superior y blanca la inferior","Blanca la superior y verde la inferior"],a:0,e:"«Blanco sobre rojo, práctico a bordo». Es justo la inversa de la pesca no de arrastre (rojo sobre blanco).",r:"Regla 29 a) i)"},
{id:"c3",t:"cp",q:"Un buque de práctico en servicio de practicaje, fondeado, exhibirá:",o:["Blanca sobre roja, más las luces o la marca de fondeo","Solo las luces de fondeo","Blanca sobre roja, más luces de costado y alcance","Dos luces rojas en línea vertical"],a:0,e:"En navegación añade costados y alcance; fondeado, las luces o marca de fondeo.",r:"Regla 29 a) iii)"},
{id:"c4",t:"cp",q:"¿Qué buque exhibe las luces de la figura, vistas por la proa?",o:["Un buque restringido por su calado","Un buque varado","Un buque sin gobierno con arrancada","Un buque con capacidad de maniobra restringida"],a:0,fig:{k:"n",v:"Por nuestra proa",l:[["r",160,34],["r",160,52],["r",160,70],["w",112,80],["w",120,46],["g",98,100],["r",136,100]]},e:"Tres rojas en vertical + luces normales de buque a motor (topes y costados) = restringido por su calado. Un sin gobierno serían dos rojas y sin luz de tope.",r:"Regla 28"},
{id:"c5",t:"cp",q:"Un buque de práctico que no está en servicio de practicaje exhibirá:",o:["Las luces o marcas prescritas para un buque similar de su eslora","Blanca sobre roja","Las luces de buque sin gobierno","Ninguna luz"],a:0,e:"Fuera de servicio, es un buque más.",r:"Regla 29 b)"},
{id:"c6",t:"cp",q:"Ante un buque restringido por su calado que exhibe las señales de la Regla 28, los demás buques (salvo los sin gobierno y con maniobra restringida):",o:["Evitarán, si las circunstancias lo permiten, entorpecer su tránsito seguro","Deben mantener rumbo y velocidad","No tienen ninguna obligación especial","Deben fondear"],a:0,e:"El restringido por calado no tiene «preferencia» en sentido estricto: los demás deben evitar entorpecer su paso.",r:"Regla 18 d)"},
{id:"c7",t:"cp",q:"Las luces de la figura indican:",o:["Un buque de práctico en servicio de practicaje, con arrancada, visto por su estribor","Un pesquero no de arrastre","Un velero","Un buque fondeado"],a:0,fig:{k:"n",v:"De través",l:[["w",120,40],["r",120,60],["g",150,98]]},e:"Blanca sobre roja = práctico. La verde de abajo es su costado de estribor: en navegación. El práctico no lleva luz de tope.",r:"Regla 29 a)"},

// ---------- Fondeados y varados ----------
{id:"o1",t:"fon",q:"Un buque fondeado de 50 metros de eslora o más exhibirá:",o:["En la proa, una luz blanca todo horizonte y, a popa o cerca de ella, otra blanca todo horizonte más baja que la de proa","Dos luces blancas en línea vertical a proa","Una sola luz blanca en el tope","Dos luces rojas en línea vertical"],a:0,e:"Al revés que en navegación: la de proa es la MÁS ALTA.",r:"Regla 30 a)"},
{id:"o2",t:"fon",q:"Un buque fondeado de eslora inferior a 50 metros:",o:["Podrá exhibir una sola luz blanca todo horizonte en el lugar más visible","Está obligado a exhibir siempre dos luces","Exhibirá una luz roja","No exhibirá ninguna luz"],a:0,e:"< 50 m: basta una blanca todo horizonte.",r:"Regla 30 b)"},
{id:"o3",t:"fon",q:"La marca diurna de un buque fondeado es:",o:["Una bola, en la parte de proa","Dos bolas en línea vertical","Un cilindro","Un cono con el vértice hacia abajo"],a:0,e:"Una bola a proa.",r:"Regla 30 a) i)"},
{id:"o4",t:"fon",q:"Un buque varado exhibirá:",o:["Las luces de fondeo y, además, dos luces rojas todo horizonte en línea vertical; de día, tres bolas en línea vertical","Tres luces rojas en línea vertical","Las luces de fondeo y una luz amarilla","Dos luces rojas y dos bolas"],a:0,e:"Fondeo + dos rojas (las mismas que «sin gobierno»: un varado no puede maniobrar). De día, tres bolas.",r:"Regla 30 d)"},
{id:"o5",t:"fon",q:"Un buque fondeado de 100 metros de eslora o más:",o:["Utilizará además sus luces de trabajo, o equivalentes, para iluminar sus cubiertas","Exhibirá tres luces de fondeo","Exhibirá un cilindro","Exhibirá también la luz de alcance"],a:0,e:"Desde 100 m es obligatorio iluminar las cubiertas; por debajo, es potestativo.",r:"Regla 30 c)"},
{id:"o6",t:"fon",q:"Una embarcación de eslora inferior a 7 metros, fondeada fuera de un paso estrecho, canal, fondeadero o zona de navegación habitual:",o:["No está obligada a exhibir las luces o la marca de fondeo","Debe exhibir dos luces blancas","Debe exhibir una bola y una luz roja","Debe mantener encendidas las luces de costado"],a:0,e:"Exención para < 7 m fuera de zonas de paso.",r:"Regla 30 e)"},
{id:"o7",t:"fon",q:"Las luces blancas de la figura, a distinta altura y separadas horizontalmente, sin ninguna otra visible, indican:",o:["Un buque fondeado de 50 metros o más, con la proa hacia la izquierda de la figura","Un buque fondeado con la proa hacia la derecha de la figura","Un buque de propulsión mecánica visto por la popa","Un buque remolcando"],a:0,fig:{k:"n",v:"De través",l:[["w",70,54],["w",176,82]]},e:"Fondeado: la luz de proa es la más alta. Si la más alta está a la izquierda, la proa está a la izquierda. Un buque navegando de través mostraría además una luz de costado.",r:"Regla 30 a)"},
{id:"o8",t:"fon",q:"¿Qué indican las luces de la figura?",o:["Un buque varado","Un buque sin gobierno fondeado","Un buque restringido por su calado","Un buque con maniobra restringida fondeado"],a:0,fig:{k:"n",v:"De través",l:[["w",70,60],["w",176,84],["r",124,36],["r",124,56]]},e:"Dos blancas de fondeo + dos rojas en vertical = varado.",r:"Regla 30 d)"},
{id:"o9",t:"fon",q:"Los buques de eslora inferior a 12 metros, cuando están varados:",o:["No están obligados a exhibir las luces o marcas de buque varado","Deben exhibir siempre tres bolas","Exhiben una luz roja todo horizonte","Exhiben luces de costado"],a:0,e:"Exención para < 12 m varados.",r:"Regla 30 f)"},

// ---------- Marcas diurnas ----------
{id:"m1",t:"mar",q:"Un buque exhibe de día la marca de la figura. Se trata de:",o:["Un buque sin gobierno","Un buque con capacidad de maniobra restringida","Un buque remolcando con un remolque de más de 200 metros","Un buque varado"],a:1,fig:{k:"d",v:"De día",s:["ball","bic","ball"]},e:"Bola-bicónica-bola = maniobra restringida (como roja-blanca-roja de noche).",r:"Regla 27 b) ii)"},
{id:"m2",t:"mar",q:"La marca de la figura identifica a:",o:["Un buque dedicado a la pesca","Un buque de vela que navega también a motor","Un buque remolcando","Un buque con capacidad de maniobra restringida"],a:0,fig:{k:"d",v:"De día",s:["pesca"]},e:"Dos conos unidos por los vértices = pesca (de arrastre o no).",r:"Regla 26"},
{id:"m3",t:"mar",q:"La marca de la figura identifica a:",o:["Un buque restringido por su calado","Un buque fondeado","Un buque sin gobierno","Un buque de práctico"],a:0,fig:{k:"d",v:"De día",s:["cyl"]},e:"Cilindro = restringido por su calado (de noche, tres rojas).",r:"Regla 28"},
{id:"m4",t:"mar",q:"Un buque exhibe de día las marcas de la figura, en línea vertical. Se trata de:",o:["Un buque dedicado al dragado de minas","Un buque varado","Un buque sin gobierno con arrancada","Un buque fondeado de más de 100 metros"],a:1,fig:{k:"d",v:"De día",s:["ball","ball","ball"]},e:"Tres bolas en línea VERTICAL = varado. El dragaminas también usa tres bolas, pero en triángulo (tope y extremos de la verga).",r:"Regla 30 d) ii)"},
{id:"m5",t:"mar",q:"La marca de la figura, exhibida a proa, identifica a:",o:["Un buque de vela que navega también a motor","Un pesquero con el aparejo extendido","Un buque fondeado","Un buque de práctico"],a:0,fig:{k:"d",v:"De día",s:["coneD"]},e:"Cono con el vértice hacia abajo = vela + motor. Con el vértice hacia arriba señala el aparejo de un pesquero.",r:"Regla 25 e)"},
{id:"m6",t:"mar",q:"Las marcas de la figura identifican a:",o:["Un buque sin gobierno","Un buque varado","Un buque fondeado","Un pesquero"],a:0,fig:{k:"d",v:"De día",s:["ball","ball"]},e:"Dos bolas = sin gobierno (de noche, dos rojas). Una = fondeado; tres = varado.",r:"Regla 27 a) ii)"},
{id:"m7",t:"mar",q:"La marca de la figura identifica a:",o:["Un buque remolcando o remolcado, con un remolque de más de 200 metros","Un buque con capacidad de maniobra restringida","Un pesquero","Un buque de vela a motor"],a:0,fig:{k:"d",v:"De día",s:["bic"]},e:"Marca bicónica (conos unidos por la base) = remolque de más de 200 m.",r:"Regla 24"},
{id:"m8",t:"mar",q:"La distancia vertical entre marcas debe ser como mínimo de:",o:["0,6 metros","1 metro","1,5 metros","2 metros"],a:2,e:"1,5 m entre marcas. La bola mide al menos 0,6 m de diámetro.",r:"Anexo I, 6 b)"},
{id:"m9",t:"mar",q:"Una bola debe tener un diámetro mínimo de:",o:["0,3 metros","0,6 metros","1 metro","1,5 metros"],a:1,e:"0,6 m. El cono y el cilindro también tienen 0,6 m de diámetro de base.",r:"Anexo I, 6 a)"},
{id:"m10",t:"mar",q:"Un cilindro, como marca, debe tener:",o:["Un diámetro de al menos 0,6 metros y una altura igual al doble de su diámetro","Una altura igual a su diámetro","Un diámetro de 1 metro","Un diámetro de 0,3 metros"],a:0,e:"Diámetro ≥ 0,6 m; altura = 2 × diámetro. El cono: altura = diámetro de la base.",r:"Anexo I, 6 a) iii)"},
{id:"m11",t:"mar",q:"Un buque exhibe en la parte de proa la marca de la figura. Se trata de:",o:["Un buque fondeado","Un buque sin gobierno","Un buque varado","Un buque de práctico"],a:0,fig:{k:"d",v:"De día",s:["ball"]},e:"Una bola = fondeado.",r:"Regla 30 a) i)"},
{id:"m12",t:"mar",q:"En los buques de eslora inferior a 20 metros, las marcas:",o:["Podrán ser de dimensiones menores, proporcionadas al tamaño del buque, y la distancia entre ellas podrá reducirse","Están prohibidas","Deben tener las mismas dimensiones que en los grandes buques","Se sustituyen por banderas"],a:0,e:"Marcas a escala, proporcionadas al buque.",r:"Anexo I, 6 c)"},

// ---------- Reglas de rumbo y señales acústicas ----------
{id:"n1",t:"gen",q:"Cuando dos buques de propulsión mecánica navegan de vuelta encontrada, a rumbos opuestos o casi opuestos, con riesgo de abordaje:",o:["Cada uno caerá a estribor para pasar por la banda de babor del otro","Cada uno caerá a babor","Se apartará el que tenga al otro por su estribor","Se apartará el de menor eslora"],a:0,e:"Ambos caen a estribor y se cruzan babor con babor.",r:"Regla 14"},
{id:"n2",t:"gen",q:"Cuando dos buques de propulsión mecánica se cruzan con riesgo de abordaje, se mantendrá apartado de la derrota del otro:",o:["El que tenga al otro por su costado de estribor","El que tenga al otro por su costado de babor","El de mayor eslora","El más rápido"],a:0,e:"Quien ve al otro por estribor (es decir, quien ve su luz roja) se aparta.",r:"Regla 15"},
{id:"n3",t:"gen",q:"Se considera que un buque alcanza a otro cuando se le aproxima viniendo desde una marcación mayor de:",o:["22,5° a popa del través de este último","45° a popa del través","10° a popa del través","Cualquier marcación por la popa"],a:0,e:"Más de 22,5° a popa del través: el sector de la luz de alcance.",r:"Regla 13 b)"},
{id:"n4",t:"gen",q:"Un buque de vela que alcanza a un buque de propulsión mecánica:",o:["Debe mantenerse apartado de la derrota del buque alcanzado","Tiene preferencia por ser velero","Ambos deben caer a estribor","El buque de propulsión mecánica debe apartarse siempre"],a:0,e:"La regla de alcance prevalece: el que alcanza se aparta, sea del tipo que sea.",r:"Regla 13 a)"},
{id:"n5",t:"gen",q:"Un buque de propulsión mecánica en navegación se mantendrá apartado de la derrota de:",o:["Un buque sin gobierno","Un buque con capacidad de maniobra restringida","Un buque dedicado a la pesca y un buque de vela","Todos los anteriores"],a:3,e:"Orden de la Regla 18: sin gobierno > maniobra restringida > (calado) > pesca > vela > motor.",r:"Regla 18 a)"},
{id:"n6",t:"gen",q:"En navegación, un buque de vela se mantendrá apartado de la derrota de:",o:["Un buque dedicado a la pesca","Un buque de propulsión mecánica","Una embarcación de recreo a motor","De ninguno: el velero siempre tiene preferencia"],a:0,e:"El velero se aparta de sin gobierno, maniobra restringida y pesca.",r:"Regla 18 b)"},
{id:"n7",t:"gen",q:"Dos buques de vela con riesgo de abordaje reciben el viento por bandas distintas. Se mantendrá apartado:",o:["El que reciba el viento por babor","El que reciba el viento por estribor","El que esté a barlovento","El de mayor eslora"],a:0,e:"Bandas distintas: se aparta el que recibe el viento por babor.",r:"Regla 12 a) i)"},
{id:"n8",t:"gen",q:"Dos buques de vela con riesgo de abordaje reciben el viento por la misma banda. Se mantendrá apartado:",o:["El que esté a barlovento","El que esté a sotavento","El de menor eslora","El que navegue más rápido"],a:0,e:"Misma banda: se aparta el de barlovento.",r:"Regla 12 a) ii)"},
{id:"n9",t:"gen",q:"Una «pitada corta» es un sonido de una duración aproximada de:",o:["1 segundo","2 segundos","De 4 a 6 segundos","Medio segundo"],a:0,e:"Corta ≈ 1 s; larga, de 4 a 6 s.",r:"Regla 32 b)"},
{id:"n10",t:"gen",q:"Una «pitada larga» tiene una duración aproximada de:",o:["1 segundo","2 segundos","De 4 a 6 segundos","De 8 a 10 segundos"],a:2,e:"De 4 a 6 segundos.",r:"Regla 32 c)"},
{id:"n11",t:"gen",q:"Dos pitadas cortas significan:",o:["Caigo a estribor","Caigo a babor","Estoy dando atrás","Pretendo alcanzarle por su costado de babor"],a:1,e:"1 corta estribor, 2 cortas babor, 3 cortas atrás.",r:"Regla 34 a)"},
{id:"n12",t:"gen",q:"Tres pitadas cortas significan:",o:["Caigo a estribor","Caigo a babor","Estoy dando atrás","No entiendo su maniobra"],a:2,e:"Tres cortas: estoy dando atrás.",r:"Regla 34 a)"},
{id:"n13",t:"gen",q:"Cinco pitadas cortas y rápidas, como mínimo, indican:",o:["Que se está dando atrás","Duda sobre las intenciones o maniobras del otro buque","Que el buque está sin gobierno","Que se pretende alcanzar por babor"],a:1,e:"Señal de duda: «no entiendo su maniobra».",r:"Regla 34 d)"},
{id:"n14",t:"gen",q:"En un paso o canal angosto, dos pitadas largas seguidas de una corta significan:",o:["Pretendo alcanzarle por su costado de estribor","Pretendo alcanzarle por su costado de babor","Estoy de acuerdo con su maniobra","Caigo a estribor"],a:0,e:"2 largas + 1 corta: por su estribor. 2 largas + 2 cortas: por su babor.",r:"Regla 34 c) i)"},
{id:"n15",t:"gen",q:"En un paso estrecho, el buque que va a ser alcanzado indica su conformidad con:",o:["Larga, corta, larga, corta","Cinco pitadas cortas","Dos largas y dos cortas","Una pitada larga"],a:0,e:"Larga-corta-larga-corta (la letra «C» en morse).",r:"Regla 34 c) ii)"},
{id:"n16",t:"gen",q:"Con visibilidad reducida, un buque de propulsión mecánica con arrancada emitirá:",o:["Una pitada larga a intervalos que no excedan de 2 minutos","Dos pitadas largas cada 2 minutos","Una larga seguida de dos cortas cada 2 minutos","Un repique de campana cada minuto"],a:0,e:"Con arrancada: 1 larga. Sin arrancada: 2 largas. Ambas cada 2 minutos como máximo.",r:"Regla 35 a)"},
{id:"n17",t:"gen",q:"Con visibilidad reducida, un buque de propulsión mecánica en navegación pero parado y sin arrancada emitirá:",o:["Una pitada larga cada 2 minutos","Dos pitadas largas consecutivas, con un intervalo de unos 2 segundos entre ellas, a intervalos que no excedan de 2 minutos","Tres pitadas cortas cada minuto","Un repique de campana"],a:1,e:"Dos largas = parado sin arrancada.",r:"Regla 35 b)"},
{id:"n18",t:"gen",q:"Con visibilidad reducida, un buque de vela emitirá a intervalos que no excedan de 2 minutos:",o:["Una pitada larga","Dos pitadas largas","Una pitada larga seguida de dos cortas","Una pitada larga seguida de tres cortas"],a:2,e:"1 larga + 2 cortas: vela, pesca, sin gobierno, maniobra restringida, calado, remolcando o empujando.",r:"Regla 35 c)"},
{id:"n19",t:"gen",q:"Con visibilidad reducida, el último buque remolcado, si va tripulado, emitirá:",o:["Una pitada larga","Dos pitadas largas","Una larga seguida de dos cortas","Una larga seguida de tres cortas"],a:3,e:"1 larga + 3 cortas, inmediatamente después de la señal del remolcador.",r:"Regla 35 e)"},
{id:"n20",t:"gen",q:"Un buque fondeado de eslora inferior a 100 metros, con visibilidad reducida, hará sonar:",o:["Un repique rápido de campana de unos 5 segundos, a intervalos que no excedan de 1 minuto","Una pitada larga cada 2 minutos","Tres golpes de campana cada 2 minutos","Un gong cada 30 segundos"],a:0,e:"Campana 5 s cada minuto (desde 100 m, además gong a popa). Varado: añade tres golpes separados antes y después.",r:"Regla 35 g)"},
{id:"n21",t:"gen",q:"Se considera que existe riesgo de abordaje si:",o:["La demora o marcación de un buque que se aproxima no varía de forma apreciable","La distancia entre ambos buques aumenta","La demora cambia rápidamente","El otro buque es de mayor eslora"],a:0,e:"Demora constante + distancia que disminuye = riesgo de abordaje.",r:"Regla 7 d) i)"},
{id:"n22",t:"gen",q:"Con visibilidad reducida, detectamos solo por radar un buque a proa del través, al que no estamos alcanzando, con riesgo de abordaje. En la medida de lo posible evitaremos:",o:["Una caída a babor","Una caída a estribor","Reducir la velocidad","Cualquier maniobra"],a:0,e:"Buque a proa del través: evitar caer a babor. Buque por el través o a popa de él: evitar caer hacia él.",r:"Regla 19 d)"},
{id:"n23",t:"gen",q:"Un buque obligado a cruzar una vía de circulación de un dispositivo de separación del tráfico lo hará:",o:["Con un rumbo que forme un ángulo lo más próximo posible a la perpendicular respecto a la dirección general de la corriente del tráfico","Con un ángulo de 45°","Solo por los extremos del dispositivo","Con el rumbo que prefiera"],a:0,e:"Lo más perpendicular posible, para cruzar cuanto antes.",r:"Regla 10 c)"},
{id:"n24",t:"gen",q:"En un paso o canal angosto, los buques de eslora inferior a 20 metros y los buques de vela:",o:["No estorbarán el tránsito de un buque que solo pueda navegar con seguridad dentro de dicho paso","Tienen preferencia sobre los demás","Deben navegar por el centro del canal","Pueden fondear libremente en el canal"],a:0,e:"No deben estorbar a los buques que solo pueden navegar dentro del canal.",r:"Regla 9 b)"},
{id:"n25",t:"gen",q:"Un buque que se aproxima a un recodo de un paso estrecho donde puedan quedar ocultos otros buques emitirá:",o:["Una pitada larga","Dos pitadas cortas","Cinco pitadas cortas","Tres pitadas largas"],a:0,e:"Una larga; quien la oiga al otro lado del recodo contesta con otra larga.",r:"Regla 34 e)"},
{id:"n26",t:"gen",q:"El buque que «sigue a rumbo» (el que no tiene que apartarse):",o:["Mantendrá rumbo y velocidad, pero podrá maniobrar si es evidente que el otro no actúa como exige el reglamento","Debe mantener rumbo y velocidad en cualquier caso, aunque el abordaje sea inminente","Debe caer siempre a babor","Debe parar las máquinas"],a:0,e:"Puede maniobrar si el otro no actúa, y debe hacerlo si el abordaje ya no puede evitarse solo con la maniobra del otro (evitando, en un cruce, caer a babor).",r:"Regla 17"}
];

